data.minimal_example:
TransformableListView.builder(
  getTransformMatrix: (item) {
    final progress = item.visibleExtent / item.size.height;
    final scale = 0.3 + (0.7 * progress);
    return Matrix4.identity()
      ..translate(item.size.width / 2)
      ..scale(scale)
      ..translate(-item.size.width / 2);
  },
  itemBuilder: (ctx, i) => Container(height: 100, color: i.isEven ? Colors.grey : Colors.blue),
  itemCount: 30,
);
